<?php
require_once '_bootstrap.php';require_once __DIR__.'/../notifications.php';require_admin_permission('bookings.manage');$db=admin_db();
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';$payment=$_POST['payment_status']??'';$note=trim($_POST['admin_note']??'');
    $allowed=['pending','needs_information','confirmed','in_progress','completed','cancelled','rejected'];
    if(!in_array($status,$allowed,true)||!in_array($payment,['unpaid','pending','paid','refund_pending','refunded'],true))redirect_with_message('bookings.php','Invalid booking or payment status.');
    try{
        $db->begin_transaction();
        $previous=$db->execute_query('SELECT status,payment_status,user_email,booking_reference,admin_note,total_amount,base_amount,hotel_surcharge_total,discount_amount,offer_id FROM bookings WHERE id=? FOR UPDATE',[$id])->fetch_assoc();
        if(!$previous)throw new RuntimeException('Booking not found.');
        $old=$previous['status'];$oldPayment=$previous['payment_status'];$oldNote=trim((string)($previous['admin_note']??''));$noteChanged=$note!==''&&$note!==$oldNote;$requestedStatus=$status;
        $transitions=['pending'=>['needs_information','confirmed','cancelled','rejected'],'needs_information'=>['pending','confirmed','cancelled','rejected'],'confirmed'=>['in_progress','cancelled'],'in_progress'=>['completed','cancelled'],'completed'=>[],'cancelled'=>[],'rejected'=>[]];
        if($requestedStatus!==$old&&!in_array($requestedStatus,$transitions[$old]??[],true))throw new RuntimeException('That booking status transition is not allowed.');
        $isFinanciallyLocked=in_array($oldPayment,['paid','refund_pending','refunded'],true);
        if($isFinanciallyLocked&&$requestedStatus==='rejected')throw new RuntimeException('Paid bookings cannot be rejected. Propose a date change or process a cancellation/refund instead.');
        if($oldPayment==='paid'&&$requestedStatus==='cancelled'&&!$db->execute_query("SELECT id FROM cancellation_requests WHERE booking_id=? AND status IN ('refund_pending','approved','refunded') ORDER BY id DESC LIMIT 1",[$id])->fetch_assoc())throw new RuntimeException('Paid bookings cannot be cancelled directly. Approve a cancellation/refund request first.');
        if($requestedStatus!==$old&&in_array($requestedStatus,['needs_information','cancelled','rejected'],true)&&$note==='')throw new RuntimeException('Add a customer update before requesting information, cancelling, or rejecting a booking.');
        if($payment==='paid'&&$oldPayment!=='paid'&&!in_array($requestedStatus,['confirmed','in_progress','completed'],true))throw new RuntimeException('Confirm the booking before marking its payment as paid.');
        if($payment==='refunded'&&!in_array($oldPayment,['paid','refund_pending'],true))throw new RuntimeException('Only a paid or refund-pending booking can be refunded.');
        if($payment==='refunded'&&!$db->execute_query("SELECT id FROM cancellation_requests WHERE booking_id=? AND status='refund_pending' ORDER BY id DESC LIMIT 1",[$id])->fetch_assoc())throw new RuntimeException('Approve a cancellation refund before marking this booking as refunded.');
        $finalStatus=$payment==='paid'&&$requestedStatus==='confirmed'?'in_progress':$requestedStatus;if($payment==='paid'&&$oldPayment!=='paid'&&preg_match('/pay|payment|amount/i',$note))$note='Payment received in full.';
        $db->execute_query('UPDATE bookings SET status=?,payment_status=?,admin_note=? WHERE id=?',[$finalStatus,$payment,$note,$id]);
        $historyTransitions=[];if($old!==$requestedStatus)$historyTransitions[]=[$old,$requestedStatus,$note];if($finalStatus!==$requestedStatus)$historyTransitions[]=[$requestedStatus,$finalStatus,'Payment recorded; booking moved to in progress.'];$by=$_SESSION['admin_email'];foreach($historyTransitions as [$historyOld,$historyNew,$historyNote])$db->execute_query('INSERT INTO booking_status_history(booking_id,old_status,new_status,note,changed_by) VALUES(?,?,?,?,?)',[$id,$historyOld,$historyNew,$historyNote,$by]);
        if($payment==='paid'&&$oldPayment!=='paid'){$paymentReference='ADMIN-'.date('ymdHis').'-'.strtoupper(bin2hex(random_bytes(3)));$db->execute_query("INSERT INTO payments(booking_id,amount,method,transaction_reference,status) VALUES(?,?,'admin_manual',?,'paid')",[$id,(float)$previous['total_amount'],$paymentReference]);if(!empty($previous['offer_id'])&&(float)$previous['discount_amount']>0){$packageBase=max(0,(float)$previous['base_amount']-(float)$previous['hotel_surcharge_total']);$db->execute_query('INSERT IGNORE INTO offer_redemptions(offer_id,booking_id,user_email,base_amount,discount_amount,final_amount) VALUES(?,?,?,?,?,?)',[(int)$previous['offer_id'],$id,$previous['user_email'],$packageBase,(float)$previous['discount_amount'],(float)$previous['total_amount']]);}}
        if($payment==='refunded'&&in_array($oldPayment,['paid','refund_pending'],true)){$approvedCancellation=$db->execute_query("SELECT id,approved_refund FROM cancellation_requests WHERE booking_id=? AND status='refund_pending' ORDER BY id DESC LIMIT 1",[$id])->fetch_assoc();$refundAmount=max(0,(float)$approvedCancellation['approved_refund']);$refundReference='REFUND-'.date('ymdHis').'-'.strtoupper(bin2hex(random_bytes(3)));$db->execute_query("INSERT INTO payments(booking_id,amount,method,transaction_reference,status) VALUES(?,?,'admin_refund',?,'refunded')",[$id,-$refundAmount,$refundReference]);$db->execute_query("UPDATE cancellation_requests SET status='refunded' WHERE id=?",[(int)$approvedCancellation['id']]);}
        $reference=$previous['booking_reference']?:'#'.$id;$email=$previous['user_email'];
        if($old!==$requestedStatus&&$requestedStatus==='confirmed'&&$email)create_notification($db,'Booking confirmed','Your booking '.$reference.' has been confirmed.'.($note!==''?' '.$note:''),'user',$email,'my-bookings.php#booking-'.$id,'success',(int)$_SESSION['admin_id']);
        elseif($old!==$finalStatus&&$email){$customerLink=$finalStatus==='needs_information'?'booking.php?edit_booking='.$id:'my-bookings.php#booking-'.$id;create_notification($db,'Booking status updated','Your booking '.$reference.' is now '.str_replace('_',' ',$finalStatus).'.'.($note!==''?' '.$note:''),'user',$email,$customerLink,$finalStatus==='needs_information'?'warning':'info',(int)$_SESSION['admin_id']);}
        elseif($noteChanged&&$email){$db->execute_query('INSERT INTO booking_status_history(booking_id,old_status,new_status,note,changed_by) VALUES(?,?,?,?,?)',[$id,$finalStatus,$finalStatus,$note,$by]);create_notification($db,'Travel India update','Update for booking '.$reference.': '.$note,'user',$email,'my-bookings.php#booking-'.$id,'info',(int)$_SESSION['admin_id']);}
        if($oldPayment!==$payment&&$email)create_notification($db,'Payment status updated','Payment for booking '.$reference.' is now '.$payment.'.','user',$email,'my-bookings.php#booking-'.$id,$payment==='paid'?'success':'info',(int)$_SESSION['admin_id']);
        admin_audit($db,'status_update','booking',(string)$id,$old.' -> '.$finalStatus.'; payment '.$oldPayment.' -> '.$payment);$db->commit();
        redirect_with_message('bookings.php',$payment==='paid'&&$finalStatus==='in_progress'?'Booking confirmed, payment recorded, and customer notified.':'Booking updated and customer notified.');
    }catch(Throwable $error){try{$db->rollback();}catch(Throwable $ignored){}redirect_with_message('bookings.php',$error->getMessage());}
}
$status=trim($_GET['status']??'');$where='';if($status!==''){$safe=$db->real_escape_string($status);$where="WHERE b.status='$safe'";}$pagination=admin_paginate($db,"SELECT COUNT(*) total FROM bookings b $where");$bookings=$db->query("SELECT b.*,p.name package_name,s.name state_name FROM bookings b LEFT JOIN packages p ON p.id=b.package_id LEFT JOIN states s ON s.id=p.state_id $where ORDER BY b.created_at DESC LIMIT {$pagination['limit']} OFFSET {$pagination['offset']}");$pageTitle='Bookings';include '_header.php';?>
<div class="page-head"><div><span>India tour reservations</span><h1>Bookings</h1></div><div class="filters"><a href="bookings.php">All</a><?php foreach(['pending','needs_information','confirmed','in_progress','completed','cancelled','rejected'] as $v):?><a href="?status=<?php echo $v;?>"><?php echo str_replace('_',' ',$v);?></a><?php endforeach;?></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Reference / Customer</th><th>Indian tour</th><th>Dates</th><th>Amount (INR)</th><th>Workflow</th></tr></thead><tbody><?php while($b=$bookings->fetch_assoc()):?><tr><td><strong><?php echo e($b['booking_reference']?:'#'.$b['id']);?></strong><small><?php echo e($b['customer_name']);?><br><?php echo e($b['user_email']);?></small></td><td><?php echo e($b['package_name']?:$b['destination']);?><small><?php echo e($b['state_name']);?> · <?php echo (int)$b['people'];?> traveller(s)</small></td><td><?php echo e($b['from_date']);?><small>to <?php echo e($b['to_date']);?></small></td><td><?php echo inr($b['total_amount']);?><small><?php echo e($b['payment_status']);?></small></td><td><form class="inline-workflow" method="post"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)$b['id'];?>"><select name="status"><?php foreach(['pending','needs_information','confirmed','in_progress','completed','cancelled','rejected'] as $v):?><option value="<?php echo $v;?>" <?php echo $b['status']===$v?'selected':'';?>><?php echo str_replace('_',' ',$v);?></option><?php endforeach;?></select><select name="payment_status"><?php foreach(['unpaid','pending','paid','refund_pending','refunded'] as $v):?><option <?php echo $b['payment_status']===$v?'selected':'';?>><?php echo $v;?></option><?php endforeach;?></select><input name="admin_note" value="<?php echo e($b['admin_note']);?>" placeholder="Customer update"><button title="Save"><i class="fa-solid fa-check"></i></button></form></td></tr><?php endwhile;?></tbody></table></div></section><?php admin_pagination($pagination);?><?php include '_footer.php';?>
